def transform(grid):
    out=[row[:] for row in grid]
    h,w=len(grid),len(grid[0])
    assert h == w
    n=h
    for r in range(n):
        for c in range(n):
            if grid[r][c] != 2:
                continue
            orbit={(r,c),(c,r),(n-1-r,n-1-c),(n-1-c,n-1-r),
                   (r,n-1-c),(n-1-r,c),(c,n-1-r),(n-1-c,r)}
            vals=[grid[rr][cc] for rr,cc in orbit if grid[rr][cc] != 2]
            if not vals:
                raise ValueError(f'no symmetry source for {(r,c)}')
            if any(v != vals[0] for v in vals):
                raise ValueError(f'inconsistent symmetry sources {(r,c)}: {vals}')
            out[r][c]=vals[0]
    return out
